+#!/usr/bin/env node
+
+import { createHash } from "node:crypto";
+import { readFile, writeFile } from "node:fs/promises";
+import { dirname, isAbsolute, relative, resolve } from "node:path";
+import { fileURLToPath } from "node:url";
+
+const rootDirectory = fileURLToPath(new URL("../", import.meta.url));
+const definitionsPath = resolve(rootDirectory, "data/artifacts.sources.json");
+const outputPath = resolve(rootDirectory, "data/artifacts.json");
+const args = process.argv.slice(2);
+
+if (args.includes("--help") || args.includes("-h")) {
+  console.log(`Usage: node tools/materialize.mjs
+
+Materialize data/artifacts.json from data/artifacts.sources.json and its source files.`);
+} else {
+  try {
+    if (args.length > 0) {
+      throw new Error(`Unknown argument: ${args[0]}`);
+    }
+
+    await materialize();
+  } catch (error) {
+    console.error(error);
+    process.exitCode = 1;
+  }
+}
+
+async function materialize() {
+  let definitions;
+
+  try {
+    definitions = JSON.parse(await readFile(definitionsPath, "utf8"));
+  } catch (cause) {
+    throw new Error("Unable to read data/artifacts.sources.json", { cause });
+  }
+
+  validateDefinitions(definitions);
+
+  const artifacts = [];
+  for (const definition of definitions.toSorted((left, right) => left.ordinal - right.ordinal)) {
+    const sourcePath = resolve(rootDirectory, definition.source);
+    const relativeSourcePath = relative(rootDirectory, sourcePath);
+    if (relativeSourcePath.startsWith("..") || isAbsolute(relativeSourcePath)) {
+      throw new Error(`Source path escapes the repository: ${definition.source}`);
+    }
+
+    let source;
+    try {
+      source = await readFile(sourcePath);
+    } catch (cause) {
+      throw new Error(`Unable to read source: ${definition.source}`, { cause });
+    }
+
+    artifacts.push({
+      ...definition,
+      byteLength: source.byteLength,
+      sha256: createHash("sha256").update(source).digest("hex").toUpperCase(),
+    });
+  }
+
+  const serialized = `${JSON.stringify(artifacts, null, 2)}\n`;
+  try {
+    await writeFile(outputPath, serialized, "utf8");
+  } catch (cause) {
+    throw new Error("Unable to write data/artifacts.json", { cause });
+  }
+
+  if ((await readFile(outputPath, "utf8")) !== serialized) {
+    throw new Error("data/artifacts.json did not match the materialized output after writing");
+  }
+
+  console.log(`Materialized ${artifacts.length} artifacts to data/artifacts.json`);
+}
+
+function validateDefinitions(definitions) {
+  if (!Array.isArray(definitions)) {
+    throw new TypeError("data/artifacts.sources.json must contain an array");
+  }
+
+  const ids = new Set();
+  const ordinals = new Set();
+  const sources = new Set();
+  const expectedKeys = ["id", "ordinal", "source"];
+
+  for (const [index, definition] of definitions.entries()) {
+    if (
+      definition === null ||
+      typeof definition !== "object" ||
+      Array.isArray(definition)
+    ) {
+      throw new TypeError(`Definition at index ${index} must be an object`);
+    }
+
+    const keys = Object.keys(definition).sort();
